import{_ as l,o as t,c as r,a2 as e}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"风险与 Kill Criteria","description":"Hearth 的主要风险、全局暂停条件、阶段 Kill Criteria、项目级 Kill Criteria 与不应被 Kill 的东西。","frontmatter":{"title":"风险与 Kill Criteria","description":"Hearth 的主要风险、全局暂停条件、阶段 Kill Criteria、项目级 Kill Criteria 与不应被 Kill 的东西。","outline":[2,3]},"headers":[],"relativePath":"reference/risks.md","filePath":"reference/risks.md","lastUpdated":1793797632000}'),a={name:"reference/risks.md"};function d(o,i,n,s,h,c){return t(),r("div",null,[...i[0]||(i[0]=[e('<p class="eyebrow">RISKS</p><h1 id="风险与-kill-criteria" tabindex="-1">风险与 Kill Criteria <a class="header-anchor" href="#风险与-kill-criteria" aria-label="Permalink to &quot;风险与 Kill Criteria&quot;">​</a></h1><p class="lead">什么情况下暂停、回退或停止项目，比“继续做”更难也更重要的决策。</p><h2 id="风险与-kill-criteria-1" tabindex="-1">风险与 Kill Criteria <a class="header-anchor" href="#风险与-kill-criteria-1" aria-label="Permalink to &quot;风险与 Kill Criteria&quot;">​</a></h2><h3 id="主要风险" tabindex="-1">主要风险 <a class="header-anchor" href="#主要风险" aria-label="Permalink to &quot;主要风险&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风险</th><th>早期信号</th><th>缓解</th></tr></thead><tbody><tr><td>范围膨胀</td><td>每阶段都在新增执行器，核心闭环未稳定</td><td>以任务集和阶段门槛控制范围</td></tr><tr><td>可靠性不足</td><td>崩溃后任务丢失、重复发送</td><td>单写者、outbox、lease、故障注入</td></tr><tr><td>安全事件</td><td>越权、秘密泄露、提示词注入成功</td><td>沙箱、Broker、审批、红队</td></tr><tr><td>Token 成本失控</td><td>单任务成本高且人工分钟未下降</td><td>Context Compiler、路由、缓存、硬预算</td></tr><tr><td>外部 Agent 依赖</td><td>版本变化导致大量任务失败</td><td>适配器、版本锁定、降级到 Native/人工</td></tr><tr><td>维护负担</td><td>每周大量时间修依赖和渠道</td><td>不自研底层、减少连接器、自动升级测试</td></tr><tr><td>通知疲劳</td><td>用户关闭通知或忽略审批</td><td>注意力预算、聚合、静默、默认动作</td></tr><tr><td>记忆错误</td><td>反复引用过期或错误事实</td><td>来源、置信度、冲突、遗忘、用户纠正</td></tr><tr><td>自进化漂移</td><td>技能越用越复杂、权限变多</td><td>评估、shadow、canary、权限交集、回滚</td></tr><tr><td>多设备复杂</td><td>同步冲突、重复执行</td><td>单写者、lease、fencing、离线队列</td></tr><tr><td>产品像套壳</td><td>去掉 Codex 后没有独立价值</td><td>控制面、记忆、审批、恢复、评测</td></tr><tr><td>平台限制</td><td>浏览器登录、验证码、API 变更</td><td>人工接管、官方 API 优先、降级</td></tr><tr><td>用户信任下降</td><td>用户不理解为什么这样做或无法撤销</td><td>可解释状态、产物、回执、kill switch</td></tr><tr><td>时间投入不可持续</td><td>维护超过可支配时间</td><td>缩小范围、延迟非核心能力、自动化测试</td></tr></tbody></table><h3 id="全局暂停条件" tabindex="-1">全局暂停条件 <a class="header-anchor" href="#全局暂停条件" aria-label="Permalink to &quot;全局暂停条件&quot;">​</a></h3><p>出现以下情况时，暂停新增功能，优先修复：</p><ul><li>高风险动作发生越权；</li><li>发生秘密或敏感数据泄露；</li><li>故障注入出现重复外部副作用；</li><li>崩溃恢复率低于 95%；</li><li>用户无法撤销设备、连接或技能；</li><li>关键记忆无法遗忘；</li><li>任务状态与事实源不一致；</li><li>外部副作用无法对账。</li></ul><h3 id="阶段-kill-criteria" tabindex="-1">阶段 Kill Criteria <a class="header-anchor" href="#阶段-kill-criteria" aria-label="Permalink to &quot;阶段 Kill Criteria&quot;">​</a></h3><p><strong>第一阶段：</strong></p><ul><li>无法定义 10 个可验收的真实任务；</li><li>无法说明 Hearth 与直接使用现有工具的区别；</li><li>没有威胁模型和基本安全边界；</li><li>原型无法让用户在不看说明的情况下完成主路径；</li><li>达到 MVP 门槛后仍无法完成 8 个真实任务；</li><li>重复外部操作无法消除；</li><li>恢复依赖人工重建状态；</li><li>任务状态只能靠聊天记录推断；</li><li>后端可用但浏览器无法完成创建、查看、审批、恢复和取回产物。</li></ul><p><strong>第二阶段：</strong></p><ul><li>邮件或日历闭环需要用户频繁重建背景信息；</li><li>来源权限无法最小化；</li><li>文档、表格或网页结果无法验证；</li><li>常见任务人工时间没有下降；</li><li>不同账户或项目数据串扰；</li><li>外部写入可能重复执行或无法核对。</li></ul><p><strong>第三阶段：</strong></p><ul><li>桌面任务成功率低且无法接管；</li><li>无法证明操作没有越权；</li><li>桌面状态无法恢复；</li><li>每次桌面任务都需要大量人工介入；</li><li>失败后容易留下半完成的高风险状态。</li></ul><p><strong>第四阶段：</strong></p><ul><li>主动任务制造通知疲劳；</li><li>用户无法预测何时会被打扰；</li><li>手机审批可被重复使用或越权；</li><li>后台任务无法停止或预算失控；</li><li>高风险动作因为主动性而绕过审批。</li></ul><p><strong>第五阶段：</strong></p><ul><li>记忆错误导致持续返工；</li><li>遗忘无法传播到摘要、索引和关联内容；</li><li>方法评估可被挑选样本操纵；</li><li>新方法扩大权限或造成安全回归；</li><li>旧版本无法恢复。</li></ul><p><strong>第六阶段：</strong></p><ul><li>多设备重复执行或状态分裂；</li><li>设备丢失无法及时撤销；</li><li>迁移后任务、记忆或产物不一致；</li><li>长期运行维护成本超过产品收益；</li><li>用户无法独立备份、恢复或退出。</li></ul><h3 id="项目级-kill-criteria" tabindex="-1">项目级 Kill Criteria <a class="header-anchor" href="#项目级-kill-criteria" aria-label="Permalink to &quot;项目级 Kill Criteria&quot;">​</a></h3><p>在以下情况下，应考虑缩小产品，而不是继续加功能：</p><ul><li>完成第二阶段后仍没有稳定的 10 个真实日常任务；</li><li>人工分钟没有实质下降，用户只是在“看 Agent 工作”；</li><li>维护成本持续超过可支配时间且没有下降趋势；</li><li>仅靠换模型就能替代 Hearth 的绝大部分价值；</li><li>安全边界无法达到可接受水平；</li><li>用户不愿意把真实邮件、文件或日程交给它；</li><li>自进化持续产生不可解释的漂移；</li><li>多设备复杂度吞掉单设备体验。</li></ul><h3 id="不应被-kill-的东西" tabindex="-1">不应被 Kill 的东西 <a class="header-anchor" href="#不应被-kill-的东西" aria-label="Permalink to &quot;不应被 Kill 的东西&quot;">​</a></h3><ul><li>Event Log 和可恢复性；</li><li>审批、幂等和 Receipt；</li><li>评测与失败样本；</li><li>记忆遗忘和用户纠正；</li><li>任务卡与低打扰体验；</li><li>手动接管；</li><li>安全边界和 kill switch。</li></ul><p>这些是产品的地基，不是可以在“赶进度”时删除的功能。</p><hr>',29)])])}const k=l(a,[["render",d]]);export{p as __pageData,k as default};
